import { useGrokTheme, Image, type CSSProperties } from "grok/canvas";

/**
 * Pinned .me pack — Shelf.
 * Still-faithful materials: hi-res wall / spine / ledge JPEG data:image crops
 * from the Shelf still (dark wood grain, blank — no baked demo text). Thick
 * book spines (~110×340), recessed purple icon wells, page-edge strip, soft
 * shadows onto the ledge. Swallowtail ribbons under the ledge.
 * NO pack wordmark — header is avatar + display name + handle + bio only.
 * Replace the constants and the bots/links arrays. Leave the JSX alone. See README.md.
 */

const AVATAR = "__AVATAR_DATA_URI__";
const DISPLAY_NAME = "__DISPLAY_NAME__";
const HANDLE = "__HANDLE__";
const BIO = "__BIO__";
const FOOTER = "__FOOTER__";

type Bot = {
  name: string;
  desc: string;
  src: string;
  href: string;
};

type Link = {
  label: string;
  href: string;
  display: string;
};

// Filler replaces this array from owner setup answers.
const bots: readonly Bot[] = [
  {
    name: "__BOT0_NAME__",
    desc: "__BOT0_DESC__",
    src: "__BOT0_ICON__",
    href: "__BOT0_HREF__",
  },
];

// Filler replaces this array from owner setup answers.
const links: readonly Link[] = [
  {
    label: "__LINK0_LABEL__",
    href: "__LINK0_HREF__",
    display: "__LINK0_DISPLAY__",
  },
];

export const LAYOUT = "shelf" as const;

/** Serif stack for still-matching name and spine titles. */
const SERIF = 'Georgia, "Times New Roman", Times, serif';

/** Still-cropped wood / paper tiles (data:image JPEG). Decorative materials only. */
const WOOD_WALL = "data:image/jpeg;base64,";
const WOOD_SPINES: readonly string[] = [
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
];
const WOOD_LEDGE_TOP = "data:image/jpeg;base64,";
const WOOD_LEDGE_FACE = "data:image/jpeg;base64,";
const PAGE_EDGE = "data:image/jpeg;base64,";
const RIBBON_FABRIC = "data:image/jpeg;base64,";

function atHandle(raw: string): string {
  const trimmed = raw.trim();
  if (trimmed.length === 0) return "";
  return trimmed.startsWith("@") ? trimmed : `@${trimmed}`;
}

function Down({ color }: { color: string }): JSX.Element {
  return (
    <svg width={14} height={14} viewBox="0 0 16 16" style={{ display: "block", flexShrink: 0 }}>
      <path
        d="M8 2.5v8M4.5 7.5 8 11l3.5-3.5M3 13.5h10"
        fill="none"
        stroke={color}
        strokeWidth={1.5}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

/** Split "Writer.promo" → base + accent suffix; ".promo" → empty base + suffix. */
function splitBotName(name: string): { base: string; suffix: string } {
  const i = name.indexOf(".");
  if (i === -1) return { base: name, suffix: "" };
  if (i === 0) return { base: "", suffix: name };
  return { base: name.slice(0, i), suffix: name.slice(i) };
}

function woodBg(uri: string, extra?: CSSProperties): CSSProperties {
  return {
    backgroundImage: `url(${uri})`,
    backgroundSize: "cover",
    backgroundPosition: "center",
    backgroundRepeat: "no-repeat",
    ...extra,
  };
}

function Spine({ bot, index = 0 }: { bot: Bot; index?: number }): JSX.Element {
  const theme = useGrokTheme();
  const wood = WOOD_SPINES[index % WOOD_SPINES.length];
  const { base, suffix } = splitBotName(bot.name);
  const accent = theme.text.accent;
  const spine: CSSProperties = {
    position: "relative",
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    justifyContent: "space-between",
    gap: 10,
    flex: "0 0 112px",
    width: 112,
    minWidth: 104,
    maxWidth: 120,
    minHeight: 340,
    height: 340,
    boxSizing: "border-box",
    padding: "14px 10px 12px",
    paddingRight: 18,
    borderRadius: 12,
    border: `1px solid ${theme.border.strong}`,
    ...woodBg(wood, { backgroundColor: theme.bg.elevated }),
    boxShadow: `0 18px 36px ${theme.border.subtle}, 0 6px 12px ${theme.border.default}, 2px 2px 0 ${theme.border.strong}`,
    textDecoration: "none",
    color: theme.text.primary,
    overflow: "hidden",
  };
  const install: CSSProperties = {
    ...theme.font.caption,
    fontFamily: theme.font.family,
    display: "inline-flex",
    flexDirection: "column",
    alignItems: "center",
    justifyContent: "center",
    gap: 3,
    width: "100%",
    minHeight: 48,
    boxSizing: "border-box",
    padding: "8px 4px",
    borderRadius: 8,
    border: `1px solid ${theme.border.strong}`,
    background: theme.bg.base,
    color: theme.text.primary,
    fontWeight: theme.weight.medium,
    position: "relative",
    zIndex: 2,
  };
  return (
    <a href={bot.href} target="_blank" rel="noreferrer" style={spine}>
      {/* thick page-edge on the right (paper strip) */}
      <div
        aria-hidden
        style={{
          position: "absolute",
          top: 0,
          right: 0,
          bottom: 0,
          width: 9,
          ...woodBg(PAGE_EDGE, { backgroundColor: theme.fill.secondary, backgroundSize: "100% 100%" }),
          zIndex: 1,
          pointerEvents: "none",
          boxShadow: `inset 2px 0 4px ${theme.border.subtle}`,
        }}
      />
      {/* soft round highlight / depth wash */}
      <div
        aria-hidden
        style={{
          position: "absolute",
          inset: 0,
          background: `linear-gradient(90deg, ${theme.border.subtle} 0%, transparent 18%, transparent 72%, ${theme.border.strong} 100%), linear-gradient(180deg, ${theme.border.subtle} 0%, transparent 12%, transparent 82%, ${theme.border.strong} 100%)`,
          pointerEvents: "none",
          zIndex: 1,
          borderRadius: 12,
        }}
      />
      {/* recessed purple icon well */}
      <div
        style={{
          width: 44,
          height: 44,
          flex: "0 0 44px",
          borderRadius: 10,
          overflow: "hidden",
          background: accent,
          boxShadow: `inset 0 2px 4px ${theme.border.strong}, inset 0 -1px 0 ${theme.border.subtle}, 0 1px 0 ${theme.border.subtle}`,
          border: `1px solid ${theme.border.strong}`,
          position: "relative",
          zIndex: 2,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div
          style={{
            width: 36,
            height: 36,
            borderRadius: 7,
            overflow: "hidden",
            background: theme.bg.base,
          }}
        >
          <Image src={bot.src} alt={`${bot.name} icon`} width={36} height={36} fit="cover" />
        </div>
      </div>
      <div
        style={{
          flex: "1 1 auto",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          width: "100%",
          minWidth: 0,
          minHeight: 160,
          position: "relative",
          zIndex: 2,
          paddingRight: 2,
        }}
      >
        <p
          style={{
            margin: 0,
            fontFamily: SERIF,
            fontSize: 17,
            fontWeight: theme.weight.semibold,
            writingMode: "vertical-rl",
            letterSpacing: "0.06em",
            overflowWrap: "anywhere",
            maxHeight: 210,
            textAlign: "center",
            color: theme.text.primary,
          }}
        >
          {base.length > 0 ? <span>{base}</span> : null}
          {suffix.length > 0 ? <span style={{ color: accent }}>{suffix}</span> : null}
        </p>
      </div>
      <span style={install}>
        <Down color={theme.text.primary} />
        Install
      </span>
    </a>
  );
}

function Ribbon({ link }: { link: Link }): JSX.Element {
  const theme = useGrokTheme();
  const showDisplay = link.display.trim().length > 0 && link.display !== link.label;
  const text = showDisplay ? `${link.label} · ${link.display}` : link.label;
  const ribbon: CSSProperties = {
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    justifyContent: "flex-start",
    flex: "0 1 48px",
    width: 48,
    minWidth: 42,
    maxWidth: 56,
    minHeight: 160,
    height: 160,
    boxSizing: "border-box",
    padding: "18px 6px 30px",
    ...woodBg(RIBBON_FABRIC, {
      backgroundColor: theme.text.accent,
      backgroundSize: "cover",
    }),
    color: theme.bg.base,
    textDecoration: "none",
    clipPath: "polygon(0 0, 100% 0, 100% calc(100% - 18px), 50% 100%, 0 calc(100% - 18px))",
    boxShadow: `2px 14px 22px ${theme.border.subtle}, 0 4px 8px ${theme.border.default}`,
    ...theme.font.caption,
    fontFamily: theme.font.family,
    fontWeight: theme.weight.semibold,
    position: "relative",
  };
  return (
    <a href={link.href} target="_blank" rel="noreferrer" style={ribbon} title={text}>
      <span
        aria-hidden
        style={{
          position: "absolute",
          inset: 0,
          background: `linear-gradient(90deg, ${theme.border.strong} 0%, transparent 35%, transparent 65%, ${theme.border.subtle} 100%)`,
          opacity: 0.35,
          pointerEvents: "none",
        }}
      />
      <span
        style={{
          writingMode: "vertical-rl",
          letterSpacing: "0.06em",
          overflowWrap: "anywhere",
          maxHeight: 118,
          textAlign: "center",
          color: theme.bg.base,
          fontSize: 11,
          position: "relative",
          zIndex: 1,
        }}
      >
        {text}
      </span>
    </a>
  );
}

function Ledge({ showLinksLabel }: { showLinksLabel: boolean }): JSX.Element {
  const theme = useGrokTheme();
  return (
    <div style={{ width: "100%", minWidth: 0, position: "relative", zIndex: 2 }}>
      <div
        style={{
          position: "relative",
          height: 18,
          borderRadius: "6px 6px 0 0",
          overflow: "hidden",
          border: `1px solid ${theme.border.strong}`,
          borderBottom: "none",
          ...woodBg(WOOD_LEDGE_TOP, { backgroundColor: theme.fill.secondary }),
          boxShadow: `inset 0 1px 0 ${theme.border.subtle}`,
        }}
      />
      <div
        style={{
          position: "relative",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          gap: 8,
          minHeight: 42,
          padding: "12px 14px",
          boxSizing: "border-box",
          borderRadius: "0 0 6px 6px",
          overflow: "hidden",
          ...woodBg(WOOD_LEDGE_FACE, { backgroundColor: theme.bg.elevated, backgroundSize: "cover" }),
          boxShadow: `0 18px 32px ${theme.border.subtle}, 0 4px 10px ${theme.border.default}`,
          border: `1px solid ${theme.border.strong}`,
          borderTop: "none",
        }}
      >
        {showLinksLabel ? (
          <>
            <span
              style={{
                fontFamily: SERIF,
                fontSize: 11,
                letterSpacing: "0.22em",
                textTransform: "uppercase",
                fontWeight: theme.weight.semibold,
                color: theme.text.primary,
                position: "relative",
                zIndex: 1,
              }}
            >
              Links
            </span>
            <span
              style={{
                width: 7,
                height: 7,
                borderRadius: theme.radius.full,
                background: theme.text.accent,
                flexShrink: 0,
                position: "relative",
                zIndex: 1,
              }}
            />
          </>
        ) : null}
      </div>
    </div>
  );
}

export default function App(): JSX.Element {
  const theme = useGrokTheme();
  const handle = atHandle(HANDLE);
  const hasShelf = bots.length > 0 || links.length > 0;
  const page: CSSProperties = {
    position: "relative",
    width: "100%",
    minHeight: "100%",
    overflowX: "hidden",
    ...woodBg(WOOD_WALL, { backgroundColor: theme.bg.base, backgroundSize: "cover" }),
    color: theme.text.primary,
    fontFamily: theme.font.family,
    boxSizing: "border-box",
  };
  const band: CSSProperties = {
    position: "relative",
    zIndex: 1,
    width: "100%",
    maxWidth: 440,
    margin: "0 auto",
    boxSizing: "border-box",
    paddingTop: "max(28px, env(safe-area-inset-top, 0px))",
    paddingRight: "max(16px, env(safe-area-inset-right, 0px))",
    paddingBottom: "max(32px, env(safe-area-inset-bottom, 0px))",
    paddingLeft: "max(16px, env(safe-area-inset-left, 0px))",
    display: "flex",
    flexDirection: "column",
    alignItems: "stretch",
    gap: 22,
  };

  return (
    <div id={LAYOUT} style={page}>
      <div
        aria-hidden
        style={{
          position: "absolute",
          inset: 0,
          pointerEvents: "none",
          background: `radial-gradient(ellipse at 50% 28%, ${theme.border.subtle} 0%, transparent 55%, ${theme.border.strong} 100%)`,
          zIndex: 0,
        }}
      />
      <div style={band}>
        <header style={{ display: "flex", alignItems: "center", gap: 14, width: "100%", minWidth: 0 }}>
          <div
            style={{
              width: 64,
              height: 64,
              flex: "0 0 64px",
              borderRadius: theme.radius.full,
              overflow: "hidden",
              border: `2px solid ${theme.text.accent}`,
              background: theme.fill.secondary,
              boxShadow: `0 4px 12px ${theme.border.subtle}`,
            }}
          >
            <Image src={AVATAR} alt={`${DISPLAY_NAME} avatar`} width={64} height={64} fit="cover" />
          </div>
          <div style={{ flex: "1 1 auto", minWidth: 0 }}>
            <h1
              style={{
                ...theme.font.heading2,
                fontFamily: SERIF,
                fontWeight: theme.weight.semibold,
                letterSpacing: "-0.02em",
                margin: 0,
                overflowWrap: "anywhere",
                color: theme.text.primary,
              }}
            >
              {DISPLAY_NAME}
            </h1>
            {handle.length > 0 ? (
              <p
                style={{
                  ...theme.font.subtext,
                  fontFamily: theme.font.family,
                  color: theme.text.accent,
                  margin: "4px 0 0",
                  overflowWrap: "anywhere",
                }}
              >
                {handle}
              </p>
            ) : null}
            <p
              style={{
                ...theme.font.subtext,
                fontFamily: theme.font.family,
                color: theme.text.secondary,
                margin: "6px 0 0",
                overflowWrap: "anywhere",
              }}
            >
              {BIO}
            </p>
          </div>
        </header>

        {hasShelf ? (
          <section style={{ width: "100%", minWidth: 0, display: "flex", flexDirection: "column", gap: 0 }}>
            {bots.length > 0 ? (
              <div
                style={{
                  display: "flex",
                  flexWrap: "wrap",
                  gap: 14,
                  width: "100%",
                  minWidth: 0,
                  alignItems: "flex-end",
                  justifyContent: "center",
                  paddingBottom: 0,
                  marginBottom: -6,
                  position: "relative",
                  zIndex: 3,
                }}
              >
                {bots.map((bot, index) => (
                  <Spine key={`${bot.href}-${index}`} bot={bot} index={index} />
                ))}
              </div>
            ) : null}

            <Ledge showLinksLabel={links.length > 0} />

            {links.length > 0 ? (
              <div
                style={{
                  display: "flex",
                  flexWrap: "wrap",
                  gap: 12,
                  width: "100%",
                  minWidth: 0,
                  justifyContent: "center",
                  alignItems: "flex-start",
                  paddingTop: 0,
                  marginTop: -4,
                  position: "relative",
                  zIndex: 0,
                }}
              >
                {links.map((link, index) => (
                  <Ribbon key={`${link.href}-${index}`} link={link} />
                ))}
              </div>
            ) : null}
          </section>
        ) : null}

        <p
          style={{
            ...theme.font.caption,
            fontFamily: theme.font.family,
            color: theme.text.tertiary,
            margin: 0,
            width: "100%",
            minWidth: 0,
            overflowWrap: "anywhere",
            textAlign: "center",
          }}
        >
          {FOOTER}
        </p>
      </div>
    </div>
  );
}
